-- ============================================================================
-- Kerala Local Self-Government Bodies — Corporations & Grama Panchayats
-- MySQL 5.7+ / 8.x / MariaDB 10.x compatible
-- ============================================================================

DROP DATABASE IF EXISTS kerala_local_bodies;
CREATE DATABASE kerala_local_bodies CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kerala_local_bodies;

CREATE TABLE districts (
    district_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name             VARCHAR(60)  NOT NULL,
    headquarters     VARCHAR(60)  NOT NULL,
    num_grama_panchayats INT UNSIGNED NOT NULL DEFAULT 0,
    num_block_panchayats INT UNSIGNED NOT NULL DEFAULT 0,
    num_municipalities   INT UNSIGNED NOT NULL DEFAULT 0,
    num_corporations     INT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (district_id),
    UNIQUE KEY uq_district_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE local_bodies (
    body_id        INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name           VARCHAR(120) NOT NULL,
    body_type      ENUM('Corporation','Municipality','Panchayat') NOT NULL,
    district_id    INT UNSIGNED NOT NULL,
    area_sq_km     DECIMAL(9,2) DEFAULT NULL,
    population     INT UNSIGNED DEFAULT NULL,
    wards          INT UNSIGNED DEFAULT NULL,
    established_year SMALLINT UNSIGNED DEFAULT NULL,
    PRIMARY KEY (body_id),
    KEY idx_body_type (body_type),
    KEY idx_body_district (district_id),
    CONSTRAINT fk_body_district FOREIGN KEY (district_id)
        REFERENCES districts (district_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



